    42→  @Test
    43→  public void testGetCacheKey()
    44→  {
    45→    JavaScriptDimFilter javaScriptDimFilter = new JavaScriptDimFilter("dim", FN1, null, JavaScriptConfig.getEnabledInstance());
    46→    JavaScriptDimFilter javaScriptDimFilter2 = new JavaScriptDimFilter("di", FN2, null, JavaScriptConfig.getEnabledInstance());
    47→    Assert.assertFalse(Arrays.equals(javaScriptDimFilter.getCacheKey(), javaScriptDimFilter2.getCacheKey()));
    48→
    49→    RegexDimExtractionFn regexFn = new RegexDimExtractionFn(".*", false, null);
    50→    JavaScriptDimFilter javaScriptDimFilter3 = new JavaScriptDimFilter("dim", FN1, regexFn, JavaScriptConfig.getEnabledInstance());
    51→    Assert.assertFalse(Arrays.equals(javaScriptDimFilter.getCacheKey(), javaScriptDimFilter3.getCacheKey()));
    52→  }
    53→
    54→  @Test
    55→  public void testEquals()
    56→  {
    57→    JavaScriptDimFilter javaScriptDimFilter = new JavaScriptDimFilter("dim", FN1, null, JavaScriptConfig.getEnabledInstance());
    58→    JavaScriptDimFilter javaScriptDimFilter2 = new JavaScriptDimFilter("di", FN2, null, JavaScriptConfig.getEnabledInstance());
    59→    JavaScriptDimFilter javaScriptDimFilter3 = new JavaScriptDimFilter("di", FN2, null, JavaScriptConfig.getEnabledInstance());
    60→    Assert.assertNotEquals(javaScriptDimFilter, javaScriptDimFilter2);
    61→    Assert.assertEquals(javaScriptDimFilter2, javaScriptDimFilter3);
    62→
    63→    RegexDimExtractionFn regexFn = new RegexDimExtractionFn(".*", false, null);
    64→    JavaScriptDimFilter javaScriptDimFilter4 = new JavaScriptDimFilter("dim", FN1, regexFn, JavaScriptConfig.getEnabledInstance());
    65→    JavaScriptDimFilter javaScriptDimFilter5 = new JavaScriptDimFilter("dim", FN1, regexFn, JavaScriptConfig.getEnabledInstance());
    66→    Assert.assertNotEquals(javaScriptDimFilter, javaScriptDimFilter3);
    67→    Assert.assertEquals(javaScriptDimFilter4, javaScriptDimFilter5);
    68→  }
